def _validate_payload(data):
    """Raise ``TypeError`` when *data* is not a valid request payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data):
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload before processing it.

    Args:
        data: The request payload. In normal mode this must be a dictionary
            whose keys are strings.
        legacy_mode: If true, skip payload validation for older clients.

    Raises:
        TypeError: If validation is enabled and ``data`` is not a dictionary
            or contains non-string keys.
    """
    if not legacy_mode:
        _validate_payload(data)

    return process(data)

